      "answer": "關於室內空氣品質確保與改善，經常使用的手法主要可分為污染源控制、通風換氣與室內淨化處理三方面。污染源控制包括了建材與化學物質使用之控制、人員造成之污染物控制、機具及燃燒之污染控制；而通風換氣則為： 供給充分外氣。 稀釋污染物質。 除去污染源。 調整空間壓力控制氣流進出。 削減部分熱負荷。 排除臭氣等目的。 室內淨化處理乃指使用各種室內空氣清淨設備去除室內空氣污染物。",
