      "answer": "外氣預冷空調箱具獨立的外氣引入口，外氣經過外氣預冷空調箱 (Precooling air handle unit, PAH)，進行溫溼度調整，再送入室內，可採直接送入室內定點使之被動擴散，或以風管系統主動配送至室內各使用區域。因預冷空調箱內引入外氣時，會進行溫溼度調整，對於室內空調能源消耗較小。",
