      "answer": "全熱交換器屬於一種氣對氣之能源交換器，可提供室內大量新鮮空氣，同時將室內廢氣排出，換氣效果佳，且於換氣過程中可進行室內、外空氣熱交換。藉由室內抽引至室外的低溫空氣與室外較高溫之新鮮外氣進行溫度轉換，使引入之外氣溫度降低，減少室內空調運轉負荷，達到提供新鮮空氣及環保節能之效用，避免夏季時用電量增加。",
