      "answer": "原理以定流量抽引空氣進入特定形狀之採樣器進氣口，經慣性 微粒分徑器，將氣動粒徑小於或等於 2.5 微米 (μm) 之細懸浮微 粒 (PM2.5) 收集於濾紙上。而此濾紙於採樣前、後均於特定溫 度與溼度環境中調理後秤重，以決定所收集之 PM2.5 微粒之淨重，再除以 24 小時之採樣總體積即得微粒 24 小時之質量濃度。",
