      "question": "常用外氣換氣系統可分為幾種類型？請說明之。",
      "type": "fill_blank",
      "answer": "外氣換氣系統可分為機械通風、自然通風二種類型： 機械通風：利用機械設備強制引入室外空氣至建築物內，或將建築物內依機械設備運作方式，歸類為機械引入與機械排出二種型式，並配合採用自然通風換氣。 自然通風：利用風力換氣、溫差效應及氣體擴散等方式，促使建築物內部及外部之氣流自然流動，但採用全自然通風時，需特別考慮空間大小及通風開口面積等相關條件。",
