      "answer": "1.   獨立外氣引入：具獨立的室外空氣引入口，以機械式送風方式將外氣送入室內，可採直接送入室內或以接風管方式送入室內各使用區域。此方式之引入空氣未進行溫度或溼度調整。 獨立外氣空調箱：具獨立的室外空氣引入口，外氣經過濾裝置後，進行溫度、溼度調整，再以機械式送風方式將外氣送入室內，並可採直接送入室內或以接風管方式送入室內各使用區域。 外氣引入與空調箱混合：具獨立的室外空氣引入口，可利用機械式送風系統或空調箱之送風機，使外氣經外氣引入口進入空調箱內，且該空調箱尚有室內回風口。部分設備型式， 其外氣可流經過濾裝置，並與回風空氣混合後，藉由空調箱進行溫度、溼度調整，送入室內。 其化型式：非屬前述三種型式者，請填寫說明。",
