      "question": "請說明引入外氣於室內配送方式？",
      "type": "fill_blank",
      "answer": "引入外氣於室內配送方式為擴散型及風管強制分布型兩種： 擴散型：指將室外空氣直接由戶外引入或藉由外氣輸送總承引入室內，未使用風管強制輸送分布於各室內使用區域。以室內送風與過濾組系統方式，外氣輸送總承內抽引外氣輸送進室內，或利用外氣輸送總承內之壓力，將外氣經該風箱或銜接一段風管後，將外氣排放於室內共通環境區域 (如天花板上空間)。 風管強制分布型：指室外空氣直接由戶外引入或藉由外氣輸送總承引入室內，於室內具有風管強制輸送分布，或搭配中央空調箱之輸送風管將外氣輸送至各室內使用區域。室內風管強制分布型常因輸送風管壓力差異，導致各室內使用區域供氣量不同，故可利用加裝送風機、改變出風口尺寸大小、風管管徑或風門調整，以控制輸送至各室內使用區域之供氣量。",
