      "answer": "1.\t冷卻水塔是否定期清洗。 冷卻水塔Y 型過濾器是否定期清潔。 冷卻水塔加藥事項說明 (如除藻劑、抑制劑、抗凍劑、酸洗劑等)。 加溼器供水端之過濾或軟水系統是否定期更換或維護。 加溼及水洗系統是否定期清潔維護。 儲水桶是否定期清潔。 風扇機組軸承或皮帶是否定期檢查維護。 空調通風系統風門裝置是否定期檢查維護。 空調系統感測器與控制器是否定期檢查維護。 空調通風系統風管保溫材料是否無破損。 空調通風系統通閥是否定期檢查維護。 空調通風系統設備安裝狀態是否定期檢查維護 (如腳架、膨脹螺栓、固定螺絲、地基、墊圈等)。 空調通風系統冷媒設備是否定期檢查維護 ( 如冷媒高低壓、馬達高阻、冷媒過濾器、傷痕、腐蝕、變形、磨耗、絕緣材料剝落或脫落、閥件、凸緣、旋塞等)。 空調系統入風口過濾網是否定期檢查、清潔或更換。 外氣入風口過濾網是否定期檢查、清潔或更換。 空氣清淨設備是否定期檢查與更換濾網。 各項排氣設備是否定期檢查及維護。 斷路器或電磁開關是否定期檢查維護。 保護裝置是否定期檢查維護 (如過電流、過溫、斷水、液位或風壓開關等)。 風管內部是否定期進行除塵與消毒等清潔或更新作業。 本工作項目是針對空調系統、換氣通風系統、空氣清淨設備、風管清潔及其所對應之電力設備、必要安全防護及其他附屬設施，進行定期檢修與保養之管理措施。清潔維護之頻率視維護項目之不同，至少每 6 個月或 1 年施行一次。",
